import type { ApplicationList } from "../../core/applications/application-list";
import type { PayloadOf, NavigationTarget } from "../../runtime/topics";

type ResolvedNavigation =
  | { ok: true; href: string }
  | { ok: false; reason: "not-navigable" };

const notNavigable = { ok: false, reason: "not-navigable" } as const;

export function targetOf(
  applications: ApplicationList,
  href: string,
): NavigationTarget {
  const url = new URL(href, window.location.origin);
  const application = applications.findByPath(url.pathname);
  const base = application?.href && toAbsolute(application.href);
  if (!base) return { appId: null, path: hrefOf(url) };
  return {
    appId: application.id,
    path: hrefOf(url).slice(base.length).replace(/^\/+/, ""),
  };
}

export function resolveNavigation(
  applications: ApplicationList | null,
  { appId, path = "" }: PayloadOf<"navigation.location.update">,
): ResolvedNavigation {
  if (appId === undefined || appId === null) {
    const target = resolveWithin("", path || "/");
    return target ? { ok: true, href: hrefOf(target) } : notNavigable;
  }
  // A blank id names no route: `/studio/` carries no application segment.
  if (appId === "") return notNavigable;
  // State machine holds an app target until one lands, so nothing here has to
  // guess a route for it.
  if (!applications) return notNavigable;

  const application = applications.applications.find(
    (candidate) => candidate.id === appId,
  );
  // Known but not navigable: e.g. an SDK app that only docks panels.
  if (application && (!application.hasAppView || !application.href)) {
    return notNavigable;
  }
  // An id the list doesn't carry still navigates. Since we can't derive the
  // type from the id, we assume it is a studio route.
  // TODO: https://linear.app/sanity/issue/SDK-2233/refine-navigationlocationupdate-topic
  const base = application?.href
    ? toAbsolute(application.href)
    : `/studio/${appId}`;
  // An app-internal path is relative to its base whether or not it says so.
  const target = resolveWithin(base, path.replace(/^\/+/, ""));
  if (!target) return notNavigable;
  // A deployed core app's route has no splat, so only a query or fragment fits.
  if (
    target.pathname !== base &&
    application?.type === "coreApp" &&
    !application.isLocal
  ) {
    return notNavigable;
  }
  return { ok: true, href: hrefOf(target) };
}

/** The router may commit its own spelling of the href it was handed. */
export function normalizeHref(href: string): string {
  return hrefOf(new URL(href, window.location.origin));
}

// `null` unless the path lands inside `base`: the URL parser sees an untrusted
// path before the router does, so no off-origin host ("//host", "javascript:…")
// and no traversal out of `base` survives.
function resolveWithin(base: string, path: string): URL | null {
  const { origin } = window.location;
  // The trailing slash extends `base` instead of replacing its last segment; a
  // path that adds no segment hands that separator straight back.
  const url = new URL(path, `${origin}${base}/`);
  if (url.pathname === `${base}/`) url.pathname = base || "/";
  if (url.origin !== origin) return null;
  if (url.pathname !== base && !url.pathname.startsWith(`${base}/`)) {
    return null;
  }
  return url;
}

function hrefOf({ pathname, search, hash }: URL): string {
  return pathname + search + hash;
}

function toAbsolute(href: string): string {
  return href.startsWith("/") ? href : `/${href}`;
}
